{
  "state_of_the_evidence": [
    {
      "claim": "A Silero‑VAD gate in front of the watcher cuts CPU usage by roughly an order of magnitude while eliminating the watcher’s “speech‑on‑hum” saturation failure.",
      "evidence": "DEVICE‑GENERALISATION results: warm ungated = 61.27 % core, warm gated = 3.32 % core (ratio = 18.46×); cold ungated = 65.83 % core, cold gated = 3.95 % core (ratio = 16.68×). Hum‑sweep results: for 50‑120 Hz hum the gate’s mean probability is ≈0.0 % (no speech emitted) versus ≈60‑70 % for the ungated watcher, confirming the failure mode is removed."
    },
    {
      "claim": "The watcher’s documented “micro‑second” latency is false; on a desktop it costs ~39 ms per 100 ms of audio (≈39 % of a CPU core).",
      "evidence": "WATCHER‑COST results (device_generalisation) report 39.3 % core for a 30 s speech clip (median of timed passes, OMP/BLAS threads forced to 1). The 31.8 % figure cited in the commit message has no measurement backing and is therefore discarded."
    },
    {
      "claim": "The character‑delta metric does **not** measure subject motion; it is dominated by camera auto‑exposure drift.",
      "evidence": "EMPTY‑ROOM‑NULL results: empty‑room dot‑flip rate = 50.00 % (the theoretical maximum) vs occupied = 48.19 %; the empty‑room rate is higher, proving the delta tracks the camera, not motion. This overturns the original ASCII‑MOTION claim (retracted in HOW‑WE‑KEEP‑FOOLING‑OURSELVES)."
    },
    {
      "claim": "Row‑wise band removal eliminates the LED‑flicker nuisance without destroying speech‑related signal.",
      "evidence": "ROW‑BAND‑REMOVAL results: empty‑room flip = 0.01 % (vs 50 % raw), occupied flip ≈ 48.57 % (≈ unchanged). The row‑subtract operator reduces the row‑constant nuisance by 159× while preserving column‑wise motion (occupied column energy rises from 4.86 % to 26.20 %)."
    },
    {
      "claim": "Temporal‑median filtering removes the banding but also erases most speech‑related motion.",
      "evidence": "TEMPORAL‑MEDIAN‑FIX results: empty‑room flip = 0 % (good) but occupied flip drops to 0.48 % (k=5) and 21.43 % (k=3), showing the filter cancels genuine signal."
    },
    {
      "claim": "The GATE_FIELD under‑reporting bug (14.5×) is retracted; the field reports the correct peak.",
      "evidence": "GATE‑PEAK‑VERDICT results: for every record the reported gate field equals the true max (ratio = 1.0). The earlier 14.5× claim compared mismatched intervals and is documented as retracted (GATE‑PEAK‑COVERAGE)."
    },
    {
      "claim": "High‑pass filtering cannot solve the 150‑200 Hz hum problem; a narrow notch can attenuate 200 Hz but does not improve pitch tracking.",
      "evidence": "NOTCH‑AB results: high‑pass 60 Hz reduces 200 Hz by only ‑0.08 dB (ineffective); a 200 Hz notch gives ‑21 dB attenuation but the emitted pitch error (median 0.14 cents, p90 1.43 cents) is unchanged, confirming the filter does not fix the pitch collapse."
    },
    {
      "claim": "Fundamental‑frequency jumps are not a reliable indicator of speaker change.",
      "evidence": "F0‑SPEAKER‑CHANGE results: only the ‘children’ cell shows a significant positive correlation (ρ = 0.341, p = 0.006); all other cells are non‑significant or negative. Overall AUC ≈ 0.53, barely above chance."
    },
    {
      "claim": "A vision model (jev‑1.14.0) cannot detect speaker change from spectrogram images; accuracy equals the trivial baseline.",
      "evidence": "SPECTROGRAM‑VISION results: model accuracy = 0.333 (margin = 0.0) on a balanced 60/60 SAME vs CHANGE test, matching the always‑predict‑change baseline (AUC = 0.529)."
    },
